import{c as l,Q as i,j as r,m as e}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"更新履歴","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":1787704068000}'),t={name:"guide/changelog.md"};function o(n,a,h,s,u,d){return i(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="更新履歴" tabindex="-1">更新履歴 <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;更新履歴&quot;">​</a></h1><p>BOOTH Package Linker の変更点をまとめています。 最新の配布ファイルは <a href="https://github.com/ChanyaVRC/booth-package-linker-releases/releases" target="_blank" rel="noreferrer">GitHub Releases</a> から取得できます。</p><h2 id="v0-21-0-—-2026-08-26" tabindex="-1">v0.21.0 — 2026-08-26 <a class="header-anchor" href="#v0-21-0-—-2026-08-26" aria-label="Permalink to &quot;v0.21.0 — 2026-08-26&quot;">​</a></h2><p>v0.20.1 からの変更です。</p><h3 id="追加された機能" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>失敗したバックグラウンド処理を再試行できるようになりました</strong> — 履歴の 対象処理を右クリックし、「再試行」を選べます。</li><li><strong>アップデート処理をバックグラウンドタスクで確認できるようになりました</strong> — 更新の確認・準備・ダウンロードの進み具合を表示し、適用を始める前までは 中止できます。</li></ul><h3 id="改善" tabindex="-1">改善 <a class="header-anchor" href="#改善" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>ダウンロードとファイルの復旧をより安全にしました</strong> — 同名ファイルを 別名で保存した場合や、ダウンロード・解凍中にアプリが終了した場合も、 保存先とライブラリの記録を正しく引き継ぎます。</li><li>バックグラウンド処理の親子表示、中止、失敗時の状態反映を安定させました。</li></ul><h3 id="不具合修正" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>BOOTH アカウントを切り替えた際の同期を修正しました</strong> — 別アカウントの スキリスト、フォロー中ショップ、無料商品の情報を混同したり、未確認の情報を 削除したりしないようにしました。</li><li>商品情報の更新が重なった際に、古い情報で新しい状態を上書きしたり、 再確認が必要な商品を飛ばしたりする問題を修正しました。</li><li>失敗したハッシュ確認を再実行できない問題と、ストレージ最適化・ Unity Package 結合を重複して開始できる問題を修正しました。</li></ul><h2 id="v0-20-1-—-2026-08-24" tabindex="-1">v0.20.1 — 2026-08-24 <a class="header-anchor" href="#v0-20-1-—-2026-08-24" aria-label="Permalink to &quot;v0.20.1 — 2026-08-24&quot;">​</a></h2><p>v0.20.0 からの変更です。</p><h3 id="改善-1" tabindex="-1">改善 <a class="header-anchor" href="#改善-1" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>起動時のスキリスト確認を効率化しました</strong> — リストと所属を先に同期し、 商品情報と価格の確認はライブラリ更新後に行うようにしました。同じ起動中に 取得済みの商品情報は安全に再利用し、BOOTH への重複した問い合わせを減らします。</li><li><strong>バックグラウンド処理の表示を改善しました</strong> — 待機中の子処理がある場合も、 現在実行中の処理名を優先して表示します。</li></ul><h3 id="不具合修正-1" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-1" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>BOOTH のスキリストから削除した商品が残る問題を修正しました</strong> — 削除された商品とリストの所属を正しく反映します。</li><li>フォローを解除したショップが一覧に残る問題を修正しました。</li><li>配布が終了した無料商品がライブラリに残る場合の同期処理を修正しました。</li></ul><h2 id="v0-20-0-—-2026-08-22" tabindex="-1">v0.20.0 — 2026-08-22 <a class="header-anchor" href="#v0-20-0-—-2026-08-22" aria-label="Permalink to &quot;v0.20.0 — 2026-08-22&quot;">​</a></h2><p>v0.19.1 からの変更です。</p><h3 id="追加された機能-1" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-1" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>複数の商品へカテゴリをまとめて設定できるようになりました</strong> — 選択中の 商品へ同じカテゴリを一度に反映できます。</li></ul><h3 id="改善-2" tabindex="-1">改善 <a class="header-anchor" href="#改善-2" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>ダウンロード操作を優先するようにしました</strong> — 重複確認やストレージ解析中に ダウンロードした場合は、解析を中止してすぐにダウンロードを開始します。</li><li><strong>設定やメモなどを保存できなかった場合の案内を改善しました</strong> — 読み取り専用などで保存できない状態を、画面上で確認できるようにしました。</li><li>配布ファイルからテスト用ファイルや開発用情報を除外し、内容を整理しました。</li></ul><h3 id="不具合修正-2" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-2" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>アプリ起動後に BOOTH のリンクを開いても反映されない問題を修正しました</strong> — 起動済みの画面へリンクを渡し、最小化中は前面へ戻すようにしました。</li><li><strong>スキリスト同期の件数と価格情報を修正しました</strong> — 同じ商品を重複して数えず、 一時的に価格を取得できなかった場合も保存済みの価格を維持します。</li><li>設定の一部だけを変更した際に、変更していない値まで消えることがある問題を 修正しました。</li><li>カテゴリの保存失敗や、待機中の処理状態が成功したように表示される問題を 修正しました。</li></ul><h2 id="v0-19-1-—-2026-08-17" tabindex="-1">v0.19.1 — 2026-08-17 <a class="header-anchor" href="#v0-19-1-—-2026-08-17" aria-label="Permalink to &quot;v0.19.1 — 2026-08-17&quot;">​</a></h2><p>v0.19.0 からの変更です。</p><h3 id="改善-3" tabindex="-1">改善 <a class="header-anchor" href="#改善-3" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>アプリの応答性と安定性を向上させました</strong> — BOOTH へのログイン確認や セッション管理を改善し、同じ確認を何度も繰り返さないようにしました。 ブラウザのプロファイルごとにセッションを保存するようにしました。</li><li><strong>商品情報の更新をより正確にしました</strong> — キャッシュされた情報と 新しい応答を区別し、古い情報で上書きしないようにしました。</li><li><strong>バックグラウンド処理の表示を改善しました</strong> — 同じ内容の通知が 重なった場合に画面がちらつかないようにしました。</li><li><strong>セール開始やショップの新着確認が重なった場合の動作を改善しました</strong> — 同じ確認を同時に何度も実行しないようにしました。</li></ul><h3 id="不具合修正-3" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-3" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>ダウンロード情報の表示が正しく更新されない問題を修正しました</strong> — 同じ内容の通知でも、ダウンロードの進み具合が変わった場合は 正しく画面に反映されるようにしました。</li><li><strong>アプリ終了時の状態保存を改善しました</strong> — 終了時の更新準備が 重複して実行されないようにしました。</li></ul><h2 id="v0-19-0-—-2026-08-15" tabindex="-1">v0.19.0 — 2026-08-15 <a class="header-anchor" href="#v0-19-0-—-2026-08-15" aria-label="Permalink to &quot;v0.19.0 — 2026-08-15&quot;">​</a></h2><p>v0.18.3 からの変更です。</p><h3 id="追加された機能-2" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-2" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>バックグラウンド処理を一覧で確認できるようになりました</strong> — 起動時の更新、 ライブラリ・ショップ・スキリストの同期、ダウンロード、重複確認、 アーカイブ、ストレージ最適化、Unity Package の結合を、親子のまとまりと 進み具合で確認できます。中止、スキップ理由、アプリを開いてから完了・失敗・ 中止した履歴も確認できます。詳しくは <a href="/guide/background-tasks">バックグラウンドタスク</a> をご覧ください。</li></ul><h3 id="改善-4" tabindex="-1">改善 <a class="header-anchor" href="#改善-4" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>ダウンロードとファイル操作をより安全にしました</strong> — ダウンロード、 手動取り込み、アーカイブ、復元、削除が重なった場合や、中止・失敗・ 強制終了が起きた場合も、既存のファイルと記録を守り、再試行できるように しました。</li><li><strong>バックアップの読み込みをより安全にしました</strong> — 内容をすべて確認してから まとめて反映し、途中で失敗・終了した場合は元の状態へ戻せるようにしました。 大きすぎるバックアップや画像も、安全に処理を中止します。</li><li>BOOTH の応答や商品画像が大きすぎる、壊れている、途中で止まる場合に、 処理が止まり続けないようにしました。極端に大きいフォルダや Unity Package も、使用メモリを抑えて安全に打ち切ります。</li></ul><h3 id="不具合修正-4" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-4" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>「このアプリで開く」の登録状態を正しく判定するようにしました</strong> — 別の場所にあるアプリが登録されている場合は未登録として表示し、起動した だけでその関連付けを上書きしません。</li><li>BOOTH から不完全な商品情報が返った場合や複数の更新が重なった場合に、 ファイルを誤って削除済みと判断したり、新しい状態を古い情報で戻したりする 問題を修正しました。</li><li>ショップ・スキリスト・設定などの読み込みが一度失敗すると空のままになる 問題と、一覧更新や画面を閉じたときにキーボード操作位置が失われる問題を 修正しました。</li><li>Unity への取り込みを中止したタイミングによって、処理が完了しないことがある 問題を修正しました。</li></ul><h2 id="v0-18-3-—-2026-08-09" tabindex="-1">v0.18.3 — 2026-08-09 <a class="header-anchor" href="#v0-18-3-—-2026-08-09" aria-label="Permalink to &quot;v0.18.3 — 2026-08-09&quot;">​</a></h2><p>v0.18.2 からの変更です。</p><h3 id="改善-5" tabindex="-1">改善 <a class="header-anchor" href="#改善-5" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>バックアップをより安全にしました</strong> — 手動で設定した商品画像も一緒に保存・ 復元できるようにしました。別の PC で読み込むときは、その PC のダウンロード先を 維持し、ファイル本体が含まれていない項目を未取得の状態に戻します。</li><li>設定画面とショートカット一覧の説明を実際の動作に合わせ、通信・更新・ ストレージ整理などの対象が分かりやすくなるよう整えました。</li><li>BOOTH アカウントでの購入確認で、認証対象の商品が一致することを サーバー側でも確認するようにしました。</li></ul><h3 id="不具合修正-5" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-5" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>公開中の商品ページを開けない問題を修正しました</strong> — スキリストから削除した 履歴や購入ライブラリから一時的に見えない状態を、商品の非公開と誤判定しない ようにしました。</li><li>商品ページやショップをブラウザで開けなかった場合、何も起きないように見えていた 問題を修正し、エラーを画面に表示するようにしました。</li><li>アップデートの自動確認を OFF にしたあとも、準備済みの更新が終了時に適用される ことがある問題を修正しました。</li></ul><h2 id="v0-18-2-—-2026-08-08" tabindex="-1">v0.18.2 — 2026-08-08 <a class="header-anchor" href="#v0-18-2-—-2026-08-08" aria-label="Permalink to &quot;v0.18.2 — 2026-08-08&quot;">​</a></h2><p>v0.18.0 からの変更です。</p><h3 id="改善-6" tabindex="-1">改善 <a class="header-anchor" href="#改善-6" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>商品が多いときの操作を軽くしました</strong> — グループ表示の切り替え・絞り込み・ 一括選択の待ち時間を短くし、検索結果もより早く切り替わるようにしました。</li><li>ライブラリやフォロー中ショップの同期で保存処理をまとめ、同期中も画面が 固まりにくくしました。</li><li>Chrome などから BOOTH のログイン情報を確認する処理を軽くし、起動直後の 引っかかりを減らしました。</li></ul><h3 id="不具合修正-6" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-6" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>ライブラリのページ数を読み取れない場合でも最後まで確認し、未確認の商品を 誤って「非公開」にしないようにしました。</li><li>停電や強制終了が保存と重なっても、ライブラリや設定が壊れにくくしました。 また、古いバージョンのアプリを起動しても、新しい設定が消えないようにしました。</li><li>古いライブラリデータの読み直しやアーカイブ中の商品情報更新によって、 ファイルの記録や作成済みの ZIP が失われる問題を修正しました。</li><li>保存先フォルダを変更したあとにアーカイブを復元すると、復元したファイルを アプリが見失う問題を修正しました。</li><li>解凍を中断したとき、以前からあるファイルを残し、今回書き出した分だけを 片付けるようにしました。</li><li>「フォルダ構成を保ってコピー」で、コピー先の同名ファイルを上書きせず、 <code>(2)</code> などを付けた別名で保存するようにしました。</li><li>PC 名の変更などで端末の確認に失敗しても、購入済みライセンスの記録を 手元から削除しないようにしました。</li><li>BOOTH 以外のサイトへログイン情報を送らないよう通信先の確認を強化し、 アプリ内に意図しない別画面が開かないようにしました。</li><li>スキリストの「未所持」の件数、一時停止中の表示、終了直前の通信記録などの 細かな不具合を修正しました。</li></ul><h2 id="v0-18-0-—-2026-08-07" tabindex="-1">v0.18.0 — 2026-08-07 <a class="header-anchor" href="#v0-18-0-—-2026-08-07" aria-label="Permalink to &quot;v0.18.0 — 2026-08-07&quot;">​</a></h2><p>v0.17.0 からの変更です。</p><h3 id="追加された機能-3" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-3" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>価格の推移をグラフで見られるようになりました</strong> — スキリストのカードを 右クリック →「📈 価格の推移」で、その商品の値段が今までどう動いたかを 階段状のグラフで表示します。グラフにマウスを乗せるか ← → キーを押すと、 その時の値段と「いつからいつまでその値段だったか」が分かります。 値段のチェックはアプリの起動時と手動同期のときに行うので、 <strong>アプリを起動していない間の値動きは記録されません</strong>。 VRChat 関連の商品では、公開データセット <a href="https://mametarogg.github.io/" target="_blank" rel="noreferrer">Boopa</a> のデータも合わせて表示され、 この PC で記録を取り始める前の期間も埋まります。詳しくは <a href="/guide/wishlist#価格の推移">スキリストの「価格の推移」</a>をご覧ください。</li><li><strong>設定に「外部との通信」を追加しました</strong> — このアプリがどこに接続して 何を送っているかの一覧です。実際の通信内容も、その下の「ログ」で そのまま確認できます。</li></ul><h3 id="改善-7" tabindex="-1">改善 <a class="header-anchor" href="#改善-7" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>スキリストタブに出ていた件数バッジを外しました。常に総数が出ているだけで、 スキリスト画面を開けば分かる情報だったためです。</li></ul><h3 id="不具合修正-7" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-7" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>ダウンロードの再開時に、サーバー側の応答によっては失敗することがある 問題を修正しました (Windows で発生)。</li></ul><h2 id="v0-17-0-—-2026-08-06" tabindex="-1">v0.17.0 — 2026-08-06 <a class="header-anchor" href="#v0-17-0-—-2026-08-06" aria-label="Permalink to &quot;v0.17.0 — 2026-08-06&quot;">​</a></h2><p>v0.16.1 からの変更です。</p><h3 id="追加された機能-4" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-4" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>メインタブが左のアイコンバーになりました</strong> — ライブラリ / ショップ / スキリスト / 設定 のタブが、画面上部から左端の縦のアイコンバーに 変わりました。上のバーがなくなった分、画面を縦に広く使えます。 アイコンにマウスを乗せると名前が表示され、「…」メニューはバーの いちばん下にあります。以前のように上部にタブを表示したい場合は、 設定の「メインタブを左のアイコンバーで表示」を OFF にしてください。</li></ul><h3 id="改善-8" tabindex="-1">改善 <a class="header-anchor" href="#改善-8" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>ウィンドウの大きさを変えたときの商品一覧の並べ直しを安定させ、 そのとき内部で記録されていたエラーを解消しました。</li></ul><h2 id="v0-16-1-—-2026-08-05" tabindex="-1">v0.16.1 — 2026-08-05 <a class="header-anchor" href="#v0-16-1-—-2026-08-05" aria-label="Permalink to &quot;v0.16.1 — 2026-08-05&quot;">​</a></h2><p>v0.16.0 からの変更です。</p><h3 id="不具合修正-8" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-8" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>ブラウザの「BOOTH Package Linker で DL」から追加した商品の名前や画像が 取得されず、「(item 番号)」のまま表示される問題を修正しました (v0.16.0 で発生)。すでにこの状態になっている商品も、アプリを更新すると 自動で名前と画像を取り直します。</li><li>BOOTH からの応答に一部欠けがあった場合でも、取得済みの商品情報 (名前・画像・ショップ情報・削除済みの印など) を消さず、取得できた分だけを 反映するようにしました。</li></ul><h2 id="v0-16-0-—-2026-08-05" tabindex="-1">v0.16.0 — 2026-08-05 <a class="header-anchor" href="#v0-16-0-—-2026-08-05" aria-label="Permalink to &quot;v0.16.0 — 2026-08-05&quot;">​</a></h2><p>v0.15.3 からの変更です。</p><h3 id="追加された機能-5" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-5" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>検索の条件を組み合わせられるようになりました</strong> — ライブラリとスキリストの 検索欄で、空白で区切った語をすべて含むものを探せるほか、<code>shop:ショップ名</code> / <code>tag:タグ</code> / <code>memo:メモ</code> の指定や、先頭に <code>-</code> を付けた除外ができるように なりました。<code>&quot;Blue Avatar&quot;</code> のように <code>&quot;</code> で囲むと、空白を含むひとつづきの 語句として検索します。詳しくは<a href="/guide/library#複合検索">ライブラリの複合検索</a>を ご覧ください。</li><li><strong>スキリストのグループ表示</strong> — スキリストでも ▦ ボタンから、リスト / BOOTH カテゴリ / ショップ / 追加時期 / 価格帯 ごとの見出し付きセクションに 分けて表示できるようになりました。見出しを押すと折りたためます。</li><li><strong>アプリを閉じるときに自動で更新</strong> — 新しいバージョンが見つかったら、アプリを 使っているあいだに裏で更新ファイルをダウンロードしておき、次にアプリを閉じた タイミングで適用する設定を追加しました (最初から ON)。閉じたあとにアプリが 勝手に起動し直すことはありません。詳しくは <a href="/guide/settings#アップデート">設定のアップデート</a>をご覧ください。</li><li><strong>完全重複・旧バージョンの整理 (ストレージ最適化)</strong> — 設定の「重複検出」が 「ストレージ最適化と重複表示」になりました。「ストレージを解析」を押すと、 中身が同じファイル・フォルダや旧バージョンを、確認しながら安全に削除できます。 中身が同じグループは必ず 1 件を残し、旧バージョンは自分で選んだものだけを 削除します。削除してもライブラリからは消えず「未取得」に戻るので、BOOTH で 提供が続いていれば再ダウンロードできます。</li></ul><h3 id="改善-9" tabindex="-1">改善 <a class="header-anchor" href="#改善-9" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>スキリストの同期を安定させました。一部の商品の価格やタグを取得できなくても、 取得できた分は保存して、失敗した商品だけをあとから取り直します。取得が不完全な リストは、手元の内容を消さずに次回の起動でやり直します。</li><li>「🔄 全アイテム再取得」中の画面の更新をまとめて行うようにし、件数が多いときの 動作を軽くしました。</li><li>ZIP 版の自動更新は、安全に置き換えできない場合があるため、GitHub のリリース ページを開いて手動で更新していただく案内に変更しました。</li></ul><h3 id="不具合修正-9" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-9" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>期限切れになったダウンロードのリンクの取り直しが、より確実に成功するように しました。</li><li>スキリストで商品の追加やリストへの振り分けが一部だけ失敗したとき、失敗した 内容を手元に勝手に反映せず、「一部未反映」と表示して BOOTH 側の確認を案内する ようにしました。</li></ul><h2 id="v0-15-3-—-2026-07-26" tabindex="-1">v0.15.3 — 2026-07-26 <a class="header-anchor" href="#v0-15-3-—-2026-07-26" aria-label="Permalink to &quot;v0.15.3 — 2026-07-26&quot;">​</a></h2><p>v0.15.2 からの変更です。</p><h3 id="改善-10" tabindex="-1">改善 <a class="header-anchor" href="#改善-10" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>ライブラリに多くのアイテムやファイルがあるときの、詳細表示や商品情報の確認、 スキリストとの照合を軽くしました。</li></ul><h2 id="v0-15-2-—-2026-07-24" tabindex="-1">v0.15.2 — 2026-07-24 <a class="header-anchor" href="#v0-15-2-—-2026-07-24" aria-label="Permalink to &quot;v0.15.2 — 2026-07-24&quot;">​</a></h2><p>v0.15.1 からの変更です。</p><h3 id="不具合修正-10" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-10" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>スキリストの絞り込みで BOOTH カテゴリが階層表示されるようになりました</strong> — これまでスキリストの絞り込みでは BOOTH カテゴリが親子の区別なく平らに 並んでいました。ライブラリの絞り込みと同じように、親カテゴリの下に 子カテゴリがぶら下がる階層表示になり、親カテゴリを選ぶと、その配下の 子カテゴリのアイテムもまとめて絞り込めるようになりました。</li></ul><h2 id="v0-15-1-—-2026-07-23" tabindex="-1">v0.15.1 — 2026-07-23 <a class="header-anchor" href="#v0-15-1-—-2026-07-23" aria-label="Permalink to &quot;v0.15.1 — 2026-07-23&quot;">​</a></h2><p>v0.15.0 からの変更です。</p><h3 id="追加された機能-6" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-6" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>設定から BOOTH ログアウト</strong> — 設定画面に「BOOTH からログアウト」ボタンを 追加しました。アプリの中で BOOTH にログインしているときだけ表示され、押すと アプリ内の BOOTH ログインだけを解除します（ブラウザ側のログインや、ライセンスの 情報には影響しません）。</li></ul><h2 id="v0-15-0-—-2026-07-22" tabindex="-1">v0.15.0 — 2026-07-22 <a class="header-anchor" href="#v0-15-0-—-2026-07-22" aria-label="Permalink to &quot;v0.15.0 — 2026-07-22&quot;">​</a></h2><p>v0.14.0 からの変更です。</p><h3 id="追加された機能-7" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-7" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>アプリの中で BOOTH にログインできるようになりました</strong> — 一部の環境では、 アプリがブラウザの BOOTH ログイン状態を読み取れず、ライセンスの自動認証や ライブラリの自動取得ができないことがありました。この場合でも、ライセンス認証 画面の「BOOTH アカウントで認証」ボタンや、ライブラリの取得時に出る「ログイン」 から、アプリの中で直接 BOOTH にログインできるようになりました。一度ログイン すれば、次回の起動でもログイン状態が保持されます。</li></ul><h2 id="v0-14-0-—-2026-07-22" tabindex="-1">v0.14.0 — 2026-07-22 <a class="header-anchor" href="#v0-14-0-—-2026-07-22" aria-label="Permalink to &quot;v0.14.0 — 2026-07-22&quot;">​</a></h2><p>v0.13.2 からの変更です。</p><h3 id="追加された機能-8" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-8" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>BOOTH での購入からライセンスを自動で認証</strong> — このアプリを BOOTH で購入、 またはギフトで受け取っている場合、起動時に自動でライセンスが認証されるように なりました。キーの入力は不要です。ライセンス認証の画面には「BOOTH アカウントで 認証」ボタンも追加したので、あとから手動で実行することもできます。</li></ul><h2 id="v0-13-2-—-2026-07-20" tabindex="-1">v0.13.2 — 2026-07-20 <a class="header-anchor" href="#v0-13-2-—-2026-07-20" aria-label="Permalink to &quot;v0.13.2 — 2026-07-20&quot;">​</a></h2><p>v0.13.1 からの変更です。</p><h3 id="改善-11" tabindex="-1">改善 <a class="header-anchor" href="#改善-11" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>商品カードにマウスを合わせると出る詳細ポップアップの表示内容を、ライブラリと スキリストで整理しました。ライブラリでは自分のライブラリでの状態（アーカイブ / ゴミ箱 / 更新あり）を、スキリストでは価格・所属リスト・購入済みかどうかを 表示します。</li><li>スキリストの右クリックメニュー「カスタムカテゴリを編集」では、カスタムカテゴリ だけを編集するようにしました。BOOTH のカテゴリはライブラリのカードから 変更できます。</li></ul><h2 id="v0-13-1-—-2026-07-19" tabindex="-1">v0.13.1 — 2026-07-19 <a class="header-anchor" href="#v0-13-1-—-2026-07-19" aria-label="Permalink to &quot;v0.13.1 — 2026-07-19&quot;">​</a></h2><p>v0.13.0 からの変更です。</p><h3 id="不具合修正-11" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-11" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>設定画面の縦スクロールバーが、内容の右端ではなく画面の右端に出るように しました。</li><li>ライブラリをグループ表示にしたとき、いちばん上の見出しの上に余白が 空きすぎていたのを詰めました。</li></ul><h2 id="v0-13-0-—-2026-07-19" tabindex="-1">v0.13.0 — 2026-07-19 <a class="header-anchor" href="#v0-13-0-—-2026-07-19" aria-label="Permalink to &quot;v0.13.0 — 2026-07-19&quot;">​</a></h2><p>v0.12.1 からの変更です。</p><h3 id="追加された機能-9" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-9" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>お知らせの個別削除</strong> — お知らせ一覧の各行に ✕ ボタンが付き、いらない お知らせを 1 件ずつ消せるようになりました。</li><li><strong>予約販売の発売予定日時</strong> — スキリストの新着お知らせに、予約販売の商品の 発売予定日時が表示されるようになりました。</li></ul><h3 id="改善-12" tabindex="-1">改善 <a class="header-anchor" href="#改善-12" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>大量のアイテムでも軽快に</strong> — ライブラリ・スキリスト・グループ表示の グリッドを、画面に見えている範囲だけを描く方式に変えました。数百〜数千件 あっても、タブの初回表示・スクロール・並べ替えがなめらかになります。</li></ul><h3 id="不具合修正-12" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-12" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>ダウンロード周りの安定性を大きく改善しました。中断・再開時のファイル破損、 完了したファイルの取り違え、一括ダウンロードの進捗表示がずれる問題などを 修正しています。</li><li>メタデータの再取得やライブラリの取得で、通信やページの読み取りが一部 失敗したときに、まだ持っている商品を誤って「非公開」にしてしまう可能性を 防ぎました。</li><li>スキリスト（おすすめリスト）で、リストへ登録した直後に同期が重なると所属が 一時的に消えることがある問題や、カテゴリを変えてもカードの表示が更新 されない問題を修正しました。</li><li>設定・スキリスト・ショップなどのタブが、まれに無反応になったりスクロール 位置が飛んだりする問題を修正しました。</li><li>予約販売やセールの新着を、取得の途中で失敗したときに取りこぼさないように しました。</li><li>🆕 マークが白黒の線画で表示されることがある問題を修正しました。</li><li>ライセンスのオフライン利用やアクティベーション周りの細かな不具合を修正 しました。</li><li>このほか、全体のコード点検にもとづく多数の安定性・整合性の改善を行って います。</li></ul><h2 id="v0-12-1-—-2026-07-10" tabindex="-1">v0.12.1 — 2026-07-10 <a class="header-anchor" href="#v0-12-1-—-2026-07-10" aria-label="Permalink to &quot;v0.12.1 — 2026-07-10&quot;">​</a></h2><p>v0.12.0 からの変更です。</p><h3 id="改善-13" tabindex="-1">改善 <a class="header-anchor" href="#改善-13" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>「メタデータを再取得」が、商品のファイル構成の変化まで反映するように なりました。新しく追加されたファイルの登録、購入情報の補完、販売者が 取り下げたファイルへの「非公開」タグ付けを、再取得 1 回で行います。 変化があったときは画面右下のお知らせに件数が表示されます。</li><li>ライブラリ全体の取得でも、ブラウザ側で受け取って登録したファイルが BOOTH で取り下げられていれば「非公開」タグが付くようになりました。</li></ul><h3 id="不具合修正-13" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-13" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>配布が終わったファイルのダウンロードに失敗したとき、理由が分からない まま「失敗」とだけ表示される問題を修正しました。失敗と同時に「非公開」 タグが付き、配布が終わったためだと分かるようになります。</li></ul><h2 id="v0-12-0-—-2026-07-08" tabindex="-1">v0.12.0 — 2026-07-08 <a class="header-anchor" href="#v0-12-0-—-2026-07-08" aria-label="Permalink to &quot;v0.12.0 — 2026-07-08&quot;">​</a></h2><p>v0.11.0 からの変更です。</p><h3 id="追加された機能-10" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-10" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>販売終了のタグ</strong> — BOOTH で販売が終了した商品に「販売終了」タグが 付くようになりました (カードと詳細画面)。ダウンロード済みのファイルは そのまま使えます。</li><li>絞り込みとグループ表示でも「販売終了」を選べるようになりました。 非公開や R-18 と同じ「メタカテゴリ」の仲間として扱われます。</li></ul><h3 id="改善-14" tabindex="-1">改善 <a class="header-anchor" href="#改善-14" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>詳細画面のサムネイル画像を右クリックしたときは「画像を拡大表示」 だけが出るようになり、メニューが簡潔になりました。</li></ul><h3 id="不具合修正-14" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-14" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>商品情報がまだ取れていない商品をゴミ箱に入れても、ライブラリの 再取得でゴミ箱から勝手に戻ってしまうことがある問題を修正しました。 同じ条件で「更新あり」の印が消えてしまう問題も直しています。</li></ul><h2 id="v0-11-0-—-2026-07-07" tabindex="-1">v0.11.0 — 2026-07-07 <a class="header-anchor" href="#v0-11-0-—-2026-07-07" aria-label="Permalink to &quot;v0.11.0 — 2026-07-07&quot;">​</a></h2><p>v0.10.2 からの変更です。</p><h3 id="追加された機能-11" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-11" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>画像の拡大プレビュー</strong> — サムネイルにカーソルを約 0.6 秒乗せると、横に拡大した 画像がポップアップします (設定で OFF 可)。サムネイルを右クリック → 「画像を拡大表示」で、画面いっぱいに表示することもできます。 カードと商品詳細画面の両方で使えます。</li><li><strong>BOOTH カテゴリの変更</strong> — 右クリック → 「カテゴリを編集」のダイアログで、 カスタムカテゴリと一緒に <strong>BOOTH カテゴリ</strong>も変更できるようになりました (手動で追加した商品への付与も同じ場所)。一括選択からまとめて設定もできます。 ここで変更したカテゴリは、商品情報の再取得でも上書きされずに残ります。</li><li><strong>🆕 最近追加 の表示</strong> — 新しく買った・受け取った・手動で追加した商品のカードに <code>🆕 最近追加</code> のタグが 7 日間つきます (使い始めの最初の取り込み分にはつきません)。</li><li><strong>追加した商品をすぐダウンロード</strong> — 「BOOTH URL から追加」やブラウザのリンクで 追加したファイルを、登録と同時に自動でダウンロードする設定を追加しました (デフォルト ON = ブラウザのリンクの従来の動きと同じ)。無料ダウンロードの新着を 自動でダウンロードする設定 (デフォルト OFF) も選べます。</li></ul><h2 id="v0-10-2-—-2026-07-06" tabindex="-1">v0.10.2 — 2026-07-06 <a class="header-anchor" href="#v0-10-2-—-2026-07-06" aria-label="Permalink to &quot;v0.10.2 — 2026-07-06&quot;">​</a></h2><p>v0.10.1 からの変更です。</p><h3 id="追加された機能-12" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-12" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>おすすめリストに含める情報を選べるように</strong> — おすすめリストのエクスポートで、 カスタムカテゴリとメモを含めるかどうかをチェックボックスで選べるようになりました。 外さなければ今までどおり全部入ります。選んだ内容は次回のエクスポートにも 引き継がれます。</li></ul><h3 id="不具合修正-15" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-15" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>販売開始・値下げの通知にサムネイルが出ない不具合を修正</strong> — 通知パネルの 「販売開始」「値下げ」の行に、商品のサムネイル画像が表示されるようになりました。 修正前に届いていた通知の分も表示されます。</li><li><strong>おすすめリストの書き出し内容を整理</strong> — 手動追加した商品をおすすめリストに 含めたとき、アプリ内部でしか使えないサムネイルの情報が出力されていたのをやめました。</li></ul><h2 id="v0-10-1-—-2026-07-03" tabindex="-1">v0.10.1 — 2026-07-03 <a class="header-anchor" href="#v0-10-1-—-2026-07-03" aria-label="Permalink to &quot;v0.10.1 — 2026-07-03&quot;">​</a></h2><p>v0.10.0 からの変更です。</p><h3 id="追加された機能-13" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-13" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>グループの見出しからまとめて選択</strong> — グループ表示の見出しにカーソルを乗せると ▶ の横にチェックボックスが現れ、そのセクションの商品を一度に選択できます (もう一度押すと解除)。親カテゴリの見出しでは子カテゴリの分も含まれます。</li><li><strong>見出しの右クリックで一括操作</strong> — グループの見出しを右クリックすると、その セクションの商品に対するまとめてダウンロード・カテゴリ追加などのメニューが 開きます。メニューを開いただけでは選択は変わらず、操作を選んだ時点で そのセクションが選択されます。</li><li><strong>Alt+クリックで子カテゴリもまとめて開閉</strong> — 見出しを Alt を押しながら クリックすると、子カテゴリの見出しも一緒に開いたり閉じたりします。</li></ul><h2 id="v0-10-0-—-2026-07-03" tabindex="-1">v0.10.0 — 2026-07-03 <a class="header-anchor" href="#v0-10-0-—-2026-07-03" aria-label="Permalink to &quot;v0.10.0 — 2026-07-03&quot;">​</a></h2><p>v0.9.1 からの変更です。</p><h3 id="追加された機能-14" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-14" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>ライブラリのグループ表示</strong> — ツールバーの ▦ ボタンで、商品一覧を選んだ軸ごとの 見出し付きセクションに分けて表示できるようになりました。 <ul><li>軸はショップ / BOOTH カテゴリ / カスタムカテゴリ / タグ / スキリスト / 取得元などから選べます。「グループ化なし」で通常の一覧に戻ります。</li><li>見出しをクリックするとそのセクションを折りたたみできます (件数付き)。 開閉の状態は軸ごとに記憶されます。</li><li>BOOTH カテゴリは親カテゴリの中に子カテゴリの見出しが入る 2 段構成です。</li><li>カスタムカテゴリ・タグ・スキリスト・取得元のように 1 つの商品が複数に 属する軸では、その商品が該当する各セクションに表示されます (例: 無料ダウンロードにあり、かつアプリで受信もした商品は両方に出ます)。</li><li>くわしくは <a href="/guide/library#グループ表示">ライブラリ画面の説明</a> をどうぞ。</li></ul></li><li><strong>グループ表示で選べる軸を設定でカスタマイズ</strong> — 設定 → 表示 の 「<a href="/guide/settings#グループ表示で選べる軸">グループ表示で選べる軸</a>」で、 ▦ ボタンの選択肢に出す軸を選べます。「あり / なし」の 2 つに分かれるだけの軸 (お気に入り・最近開いた・各状態) は、はじめは表示しない設定になっています。</li></ul><h2 id="v0-9-1-—-2026-07-02" tabindex="-1">v0.9.1 — 2026-07-02 <a class="header-anchor" href="#v0-9-1-—-2026-07-02" aria-label="Permalink to &quot;v0.9.1 — 2026-07-02&quot;">​</a></h2><p>v0.9.0 からの変更です。</p><h3 id="不具合修正-16" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-16" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>一部の ZIP が解凍に失敗する不具合を修正</strong> — フォルダ区切りにバックスラッシュ (<code>\\</code>) を使う Windows 製の ZIP で、フォルダを空ファイルと取り違えて解凍が途中で失敗することがある問題を直しました。ネストしたフォルダも正しく展開されます。</li></ul><h2 id="v0-9-0-—-2026-07-02" tabindex="-1">v0.9.0 — 2026-07-02 <a class="header-anchor" href="#v0-9-0-—-2026-07-02" aria-label="Permalink to &quot;v0.9.0 — 2026-07-02&quot;">​</a></h2><p>v0.8.0 からの変更です。</p><h3 id="追加された機能-15" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-15" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>詳細画面のファイル一覧をまとめて選べるように</strong> — 商品詳細の左側のファイル/フォルダ一覧を、Ctrl / Shift クリックで複数まとめて選べるようになりました。選んだものは一度に外部アプリへドラッグ&amp;ドロップしたり、右クリックからまとめてダウンロード・エクスプローラーで表示・名前やパスのコピーができます（フォルダ内容・Unity Package タブと同じ操作感です）。</li></ul><h3 id="改善-15" tabindex="-1">改善 <a class="header-anchor" href="#改善-15" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>ダウンロードの進捗が分かりやすく</strong> — ダウンロード中のカード下のバーが進み具合に合わせて動くようになり、解凍中は青い点滅で「展開中」だと分かるようにしました。ダウンロードキューの画面も、転送中の進み具合がその場で更新されます。</li><li><strong>ダウンロード先フォルダの変更がすぐ反映されるように</strong> — 設定でダウンロード先を変えたあと、新しいダウンロードや取り込みが正しく新しいフォルダへ入るようにしました。</li></ul><h3 id="不具合修正-17" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-17" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>起動直後にライブラリや設定が消えてしまう不具合を修正</strong> — ウイルス対策ソフトやバックアップが起動時に一瞬ファイルを掴んでいると、読み込みに失敗して空の状態で上書きし、ライブラリや設定が消えてしまうことがある問題を直しました。読み込めなかったときは保存を止めて、既存の中身を守ります。</li><li><strong>ダウンロードのバーが動かない・キューが進まない不具合を修正</strong> — ダウンロード中にバーが動かない、キューが止まる、中止したものを再ダウンロードしても始まらない、といった問題をまとめて直しました。</li><li><strong>ダウンロードの失敗でアプリごと落ちる不具合を修正</strong> — ディスクの空き不足や、他のソフトがファイルを掴んでいて書き込めないときに、アプリ全体が落ちてしまうことがある問題を直し、1 件の失敗だけで済むようにしました。</li><li><strong>完成したダウンロードがまれに捨てられて最初からやり直しになる不具合を修正</strong> — ダウンロード完了の直後にウイルス対策ソフト等がファイルを掴んでいると、完成したデータを捨てて 0 から取り直していた問題を直しました。数回待って置き換えるようにしています。</li><li><strong>一時停止したダウンロードが再起動後に固まる不具合を修正</strong> — アプリを再起動すると、一時停止中や解凍中だったダウンロードが固まったまま操作できなくなる問題を直しました。</li><li><strong>一時停止中に商品ファイルが差し替えられると壊れたデータになる不具合を修正</strong> — 一時停止と再開の間に販売者がファイルを差し替えたとき、古いデータと新しいデータが混ざって壊れることがある問題を直しました。</li><li><strong>購入済みの商品が誤って「非公開」になることがある不具合を修正</strong> — ライブラリ取得が途中で失敗したのに最後まで取得できたと誤認し、未確認のページの商品を「非公開」と判定してしまうことがある問題を直しました（前回の修正の取りこぼし分）。</li><li><strong>予約商品の販売開始通知の不具合を修正</strong> — アプリを起動したままの間に販売が始まった商品が通知されない問題と、販売者が開始日時を延期したときに古い時刻で誤って通知してしまう問題を直しました。</li><li><strong>スキリストの同期まわりの不具合を修正</strong> — 同期の途中でスキリストから削除した商品が復活してしまう問題と、フォロー中ショップの同期がログイン切れなどで失敗したときに「同期中…」の表示が消えなくなる問題を直しました。</li><li><strong>一括ダウンロード・一括選択の件数がずれる不具合を修正</strong> — 選択したあとに別の場所で削除された商品などが原因で、件数やボタンの状態がずれることがある問題を直しました。</li><li><strong>サムネイルが一度読み込みに失敗すると出ないままになる不具合を修正</strong> — 一時的な通信エラーでサムネイルが表示されなかったあと、通信が回復しても表示されないままになる問題を直しました。</li><li><strong>不正な .unitypackage による被害を防止</strong> — 細工されたパッケージが想定外の場所へファイルを書き出したり、極端に大きく展開してメモリを食い尽くしたりできないようにしました。</li><li><strong>起動直後の表示の乱れを修正</strong> — 起動時のライブラリ表示中に別の処理が重なると、消したはずの項目が残ったり件数がずれたりすることがある問題を直しました。</li></ul><h2 id="v0-8-0-—-2026-07-02" tabindex="-1">v0.8.0 — 2026-07-02 <a class="header-anchor" href="#v0-8-0-—-2026-07-02" aria-label="Permalink to &quot;v0.8.0 — 2026-07-02&quot;">​</a></h2><p>v0.7.3 からの変更です。</p><h3 id="追加された機能-16" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-16" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>予約商品が販売開始になったら通知</strong> — スキリストやフォロー中ショップの新着で見つけた<strong>販売前 (予約) の商品</strong>が販売開始になると、通知でお知らせします。販売開始の日時が分かるものは、その時刻になったら知らせます。</li></ul><h3 id="改善-16" tabindex="-1">改善 <a class="header-anchor" href="#改善-16" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>起動時の取得が速くなり、新しく買った商品が先に一覧へ</strong> — 起動時の取得を優先順位付きにしました。新しく購入した商品を先に取り込んで一覧へ出し、既にある商品の情報更新は後回しにするので、起動直後に新着が見えるまでが速くなります。</li><li><strong>BOOTH へのアクセス間隔を 1 つの設定にまとめ、初期値を短く</strong> — これまで処理ごとにばらばらだった待機時間を、設定の「ページ取得間隔」1 つにまとめました。初期値を 2 秒から 1 秒に、最短を 0.1 秒に変更したので、全体的に取得が速くなり、調整も 1 か所で済みます。</li><li><strong>「全アイテムのメタデータ再取得」が速くなりました</strong> — 商品情報をまとめて取り直すとき、1 件ごとにログイン情報を読み直していたのをやめ、1 回の読み込みで全件をまとめて処理するようにしました。</li><li><strong>非公開ファイルの見せ方を整理</strong> — 販売終了・取り下げで非公開になったファイルは、もう入手できないためカードのファイル数に数えません。詳細画面でも、<strong>非公開でまだダウンロードしていない</strong>ファイルは薄く表示して、持っているファイルと見分けやすくしました。</li></ul><h3 id="不具合修正-18" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-18" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>ライブラリ取得やメタデータ再取得がまれに止まる不具合を修正</strong> — 新しく購入した商品を含むライブラリ取得や「全アイテムのメタデータ再取得」で、内部の処理がかみ合わずに止まってしまうことがある問題を直しました。</li></ul><h2 id="v0-7-3-—-2026-07-01" tabindex="-1">v0.7.3 — 2026-07-01 <a class="header-anchor" href="#v0-7-3-—-2026-07-01" aria-label="Permalink to &quot;v0.7.3 — 2026-07-01&quot;">​</a></h2><p>v0.7.2 からの変更です。</p><h3 id="追加された機能-17" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-17" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>ダウンロードがログイン切れで失敗したとき自動でやり直し</strong> — ダウンロードの途中でログインが切れてリンクが無効になった場合、リンクを取り直して自動で 1 回だけやり直すようになりました。すぐにログインし直さなくても、そのまま完了することが増えます。</li><li><strong>Unity Package タブの「旧バージョン」表示をフォルダーと統一</strong> — Unity Package の一覧でも、古い版のファイルに「旧」ラベルが付き、フォルダー表示と同じ並べ方になりました。</li></ul><h3 id="不具合修正-19" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-19" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>壊れたファイルが「完了」と表示される不具合を修正</strong> — ダウンロードが途中で切れたときや、ログイン画面が返ってきたときに、中身が不完全なファイルが「完了」と表示され、解凍や取り込みに失敗することがありました。これらの場合は失敗として扱い、壊れたファイルを残さないようにしました。</li><li><strong>たびたびログインを求められる不具合を修正</strong> — ブラウザのログイン情報の扱いを見直し、複数のブラウザにログイン情報があるときや、起動時に複数の処理が同時に動いたときに、毎回ログインを求められてしまうことがある問題を直しました。</li><li><strong>購入済みの商品が誤って「非公開」になることがある不具合を修正</strong> — ライブラリのページ数の読み取りが、並び替えなどの条件で取りこぼし、未確認のページの商品が「非公開」と判定されることがある問題を直しました。</li><li><strong>起動時の同期と手動同期が二重に走る不具合を修正</strong> — スキリストの同期が起動時と手動操作で同時に動いて二重に処理されることがある問題を直しました（手動側はキャンセルも効くようになりました）。</li><li><strong>ショップ名・商品名の文字化けを修正</strong> — 記号や絵文字を含むショップ名・商品名が文字化けすることがある問題を直しました。</li><li><strong>フォロー中ショップの名前が出ないことがある不具合を修正</strong> — BOOTH 側の作りの違いで、フォロー中ショップの名前が表示されないことがある問題を直しました。</li><li><strong>再開したライブラリ取り込みで一部の商品を取りこぼす不具合を修正</strong> — 前回の途中から取り込みを再開したとき、新しく購入した数によっては一部のページを飛ばして取りこぼすことがある問題を直しました。</li><li><strong>解凍に失敗した zip を消せない・やり直せない不具合を修正</strong> — zip の解凍に失敗した後、その zip を削除したり再ダウンロードしたりできないことがある問題を直しました。</li><li><strong>通知をまとめた後の取りこぼし・メモリ増加を修正</strong> — 同じ商品の複数ファイルを 1 つの通知にまとめた際、まとめたファイルが二度と通知されなくなったり、使用メモリが少しずつ増えたりする問題を直しました。</li><li><strong>詳細画面の細かな操作不具合を修正</strong> — タブを切り替えた直後にキーボードのカーソルが消える、再描画でファイルの並びが変わると範囲選択の起点がずれる、などを直しました。</li><li><strong>非公開アイテムでもカテゴリを表示</strong> — 非公開になった商品でも、カテゴリが分かる場合はカテゴリを表示するようにしました。</li></ul><h3 id="改善-17" tabindex="-1">改善 <a class="header-anchor" href="#改善-17" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>画面に出るメッセージを平易な日本語に統一</strong> — 「書き出し／エクスポート」「アーカイブを戻す／解除」などの表記の揺れをなくし、エラーメッセージに混じっていた英語の専門用語を分かりやすい日本語にそろえました。ダウンロードの失敗理由も、原因が分かりやすい日本語で表示されるようになりました。</li></ul><h2 id="v0-7-2-—-2026-06-29" tabindex="-1">v0.7.2 — 2026-06-29 <a class="header-anchor" href="#v0-7-2-—-2026-06-29" aria-label="Permalink to &quot;v0.7.2 — 2026-06-29&quot;">​</a></h2><p>v0.7.1 からの変更です。</p><h3 id="不具合修正-20" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-20" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>購入済みの商品が勝手に「非公開」になる不具合を修正</strong> — BOOTH 側のライブラリ一覧ページの作りが変わったことで、起動時の自動取得が中身を読み取れず、<strong>購入済みの商品がまとめて「非公開」と判定されてしまう</strong>ことがありました。読み取りを新しい作りに対応させました。あわせて、ライブラリの中身が一度に大量に「無くなった」と見えたときは自動で「非公開」を付けないようにし、読み取りの失敗で誤って非公開になる事故を防ぎます。 <ul><li>すでに誤って非公開になった商品は、ツールバーの「ライブラリの商品情報を更新」を実行すると、まだ販売中のものは元に戻ります。</li></ul></li></ul><h3 id="追加された機能-18" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-18" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>商品詳細画面をキーボードで操作</strong> — 商品詳細のファイル一覧を、矢印キー（↑↓）でカーソル移動、Enter で選択できるようになりました。左右キーで「フォルダー」「Unity Package」タブの切り替え、Esc で一覧に戻る、複数選択（Shift+↑↓ / Ctrl+A）や選択した行のメニュー表示（メニューキー）にも対応します。割り当ては設定の「ショートカットの変更 &gt; 詳細画面」で変えられます。</li></ul><h3 id="改善-18" tabindex="-1">改善 <a class="header-anchor" href="#改善-18" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>非公開になった版を「旧バージョン」として扱う</strong> — 同じファイルに複数の版があるとき、出品者が取り下げて非公開になった版は「旧バージョン」に回し、まだ手に入る版を「現行版」として扱うようにしました。ダウンロードできない版が現行版として表示され、現行版が件数や一括ダウンロードから漏れるのを防ぎます。</li></ul><h2 id="v0-7-1-—-2026-06-28" tabindex="-1">v0.7.1 — 2026-06-28 <a class="header-anchor" href="#v0-7-1-—-2026-06-28" aria-label="Permalink to &quot;v0.7.1 — 2026-06-28&quot;">​</a></h2><p>v0.7.0 からの変更です。</p><h3 id="改善-19" tabindex="-1">改善 <a class="header-anchor" href="#改善-19" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>フォロー中ショップの新着をより早く・取りこぼしなくお知らせ</strong> — フォロー中ショップが出した新商品の確認方法を見直しました。アプリを開いてすぐ (ライブラリの取り込みを待たずに) 新着を確認するようになり、たくさんのショップをフォローしていても、まとめて出た新着を取りこぼしにくくなりました。新しく出た商品は通知ベルでお知らせします。</li></ul><h2 id="v0-7-0-—-2026-06-27" tabindex="-1">v0.7.0 — 2026-06-27 <a class="header-anchor" href="#v0-7-0-—-2026-06-27" aria-label="Permalink to &quot;v0.7.0 — 2026-06-27&quot;">​</a></h2><p>v0.6.4 からの変更です。</p><h3 id="追加された機能-19" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-19" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>詳細画面のファイル一覧をまとめて操作</strong> — 商品詳細の「フォルダ内容」と「Unity Package」の一覧で、複数のファイルをまとめて選べるようになりました。選んだものをまとめてドラッグ＆ドロップしたり、コピーしたりできます。</li><li><strong>複数の .unitypackage を1つにまとめてインポート</strong> — 選んだ複数の .unitypackage を1つに結合して、Unity へまとめて取り込めるようになりました。</li><li><strong>Unity Package 一覧の右クリックメニュー</strong> — 「Unity Package」の一覧で右クリックすると、その場で操作を選べるメニューが出るようになりました。一覧にあるものをまとめて書き出す（エクスポート）こともできます。</li><li><strong>一括ダウンロードがすぐ始まるように</strong> — 複数選択して一括ダウンロードを押したとき、すぐにダウンロード待ちへ入るようになりました（ダウンロード先の準備を後回しにして、押してから待たされないようにしました）。</li></ul><h3 id="不具合修正-21" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-21" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>同じプロジェクトが2つ表示される問題を修正</strong> — Unity に取り込むとき、取り込み先の候補に同じプロジェクトが2件並んでしまうことがある問題を修正しました。</li><li><strong>画面下で見切れるメニューを修正</strong> — 一覧の上に出るメニューが画面の下に収まりきらないとき、上向きに反転して表示するようにし、見切れないようにしました。</li><li><strong>ダウンロードが詰まる問題を修正</strong> — 解凍中をダウンロード中と分けて数えるようにし、解凍の間もほかのダウンロードが進むようにしました。</li><li><strong>スキリストの件数表示を修正</strong> — スキリストの絞り込みの件数を、表示の設定を反映したあとで数えるようにしました。</li></ul><h2 id="v0-6-4-—-2026-06-22" tabindex="-1">v0.6.4 — 2026-06-22 <a class="header-anchor" href="#v0-6-4-—-2026-06-22" aria-label="Permalink to &quot;v0.6.4 — 2026-06-22&quot;">​</a></h2><p>v0.6.3 からの変更です。</p><h3 id="追加された機能-20" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-20" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>スキリストを起動時に自動で同期</strong> — アプリを開いたときに、BOOTH のスキリスト（ほしいものリスト）の中身を自動で取り込むようになりました。新しく作ったリストや、追加・削除したアイテムが、手動で同期しなくても反映されます（1日に1回程度）。</li><li><strong>空のリストもタブで表示</strong> — アイテムが1つも入っていないスキリストも、タブとして表示されるようになりました。タブを開くと、リストが空であることを伝えるメッセージが出ます。検索や絞り込みで表示が0件になったときは、それと分かる別のメッセージを表示します。</li></ul><h3 id="改善-20" tabindex="-1">改善 <a class="header-anchor" href="#改善-20" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>不具合の調査に役立つ動作記録を充実</strong> — 画面側で起きた問題もアプリの動作記録（app.log）に残るようになり、うまく動かないときの原因を追いやすくしました。</li></ul><h2 id="v0-6-3-—-2026-06-20" tabindex="-1">v0.6.3 — 2026-06-20 <a class="header-anchor" href="#v0-6-3-—-2026-06-20" aria-label="Permalink to &quot;v0.6.3 — 2026-06-20&quot;">​</a></h2><p>v0.6.2 からの変更です。</p><h3 id="不具合修正-22" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-22" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>アップデート（更新）が実行できないことがある問題を修正</strong> — 設定画面を一度も開いていない状態で「アップデート」を実行しようとすると、確認画面が出ないまま何も起こらないことがありました。アプリ起動直後でも更新できるようにしました。</li></ul><h2 id="v0-6-2-—-2026-06-20" tabindex="-1">v0.6.2 — 2026-06-20 <a class="header-anchor" href="#v0-6-2-—-2026-06-20" aria-label="Permalink to &quot;v0.6.2 — 2026-06-20&quot;">​</a></h2><p>v0.6.1 からの変更です。</p><h3 id="追加された機能-21" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-21" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>ログ（アプリの動作記録）の削除</strong> — 設定の「キャッシュ」に、たまったログを削除して空き容量を増やせるボタンを追加しました。古いログは自動でも整理されるようになり、無制限にたまらなくなります。</li></ul><h3 id="改善-21" tabindex="-1">改善 <a class="header-anchor" href="#改善-21" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>アップデートの確認中が分かるように</strong> — 「アップデートを確認」を押したときに、確認中であることをその場で表示するようにしました。</li><li><strong>起動直後の表示を改善</strong> — 起動してすぐに「アップデート」の項目やカテゴリなどが表示されるようにしました（これまでは一覧の読み込みが終わるまで出ないことがありました）。</li><li><strong>アップデート後の一時ファイルを自動で掃除</strong> — アップデート用にダウンロードしたファイルが残らないよう、起動時に自動で削除するようにしました。</li></ul><h3 id="不具合修正-23" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-23" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>起動した直後に「v… にアップデート」を選ぼうとしても反応しないことがある問題を修正しました。</li><li>Unity にインポートするとき、1 つのプロジェクトが複数のプロジェクトとして表示されることがある問題を修正しました。</li></ul><h2 id="v0-6-1-—-2026-06-19" tabindex="-1">v0.6.1 — 2026-06-19 <a class="header-anchor" href="#v0-6-1-—-2026-06-19" aria-label="Permalink to &quot;v0.6.1 — 2026-06-19&quot;">​</a></h2><p>v0.6.0 からの変更です。</p><h3 id="不具合修正-24" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-24" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li><strong>アプリの更新が進まないことがある問題を修正</strong> — 「アップデートあり」の通知から更新しようとしたとき、ネットワークの状態によってはダウンロードが止まったまま進まず、アプリを再起動するまで更新できなくなることがありました。通信が一定時間止まったら自動で中断してやり直せるようにし、失敗したときは理由を表示するようにしました。</li></ul><h2 id="v0-6-0-—-2026-06-19" tabindex="-1">v0.6.0 — 2026-06-19 <a class="header-anchor" href="#v0-6-0-—-2026-06-19" aria-label="Permalink to &quot;v0.6.0 — 2026-06-19&quot;">​</a></h2><p>v0.5.0 からの変更です。</p><h3 id="追加された機能-22" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-22" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>ライブラリをスキリストの内容で絞り込み</strong> — ライブラリの絞り込みに「スキリスト」を追加しました。スキリストにも入れている商品だけを表示したり、スキリストのリストごと（未分類を含む）に絞り込めます。すでに持っている商品をスキリストのまとまりで振り返れます。</li></ul><h3 id="改善-22" tabindex="-1">改善 <a class="header-anchor" href="#改善-22" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>スキリストの絞り込みを所持の種類ごとに</strong> — スキリストの絞り込みで「購入済」「所有済」「追加済」をそれぞれ単独で選べるようにしました（これまでは「購入済」でまとめて絞られていました）。</li><li><strong>更新の確認アイコンを見直し</strong> — 「アップデートを確認」のアイコンを、単一の円形矢印に変更しました。</li></ul><h2 id="v0-5-0-—-2026-06-18" tabindex="-1">v0.5.0 — 2026-06-18 <a class="header-anchor" href="#v0-5-0-—-2026-06-18" aria-label="Permalink to &quot;v0.5.0 — 2026-06-18&quot;">​</a></h2><p>v0.4.3 からの変更です。</p><h3 id="追加された機能-23" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-23" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>運営からのお知らせをアプリ内で受け取り</strong> — BOOTH Package Linker からの大切なお知らせ（不具合の注意喚起や新機能の案内など）を、アプリの通知から受け取れるようになりました。</li><li><strong>「BOOTH URL から追加」で URL を自動入力</strong> — ライブラリやスキリストに BOOTH の商品 URL から追加するとき、コピー済みの商品 URL があれば入力欄に自動で入るようになりました。貼り付けの手間が省けます。</li><li><strong>戻る/進むがサブタブの移動にも対応</strong> — スキリストのリストや、ショップの絞り込みタブを切り替えたあとでも、戻る/進む（Alt+←/→ やマウスの戻る/進むボタン）で直前の表示に戻れるようになりました。</li><li><strong>Unity Package の中身に印を表示</strong> — Unity Package の一覧で、どのバリエーションのものか・どのフォルダに入っているかが一目で分かる印を付けました。</li></ul><h3 id="改善-23" tabindex="-1">改善 <a class="header-anchor" href="#改善-23" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>持っている商品の表示を分かりやすく</strong> — スキリストで、すでに持っている商品に「購入済」「所有済」「追加済」のいずれかの印を付けて、入手の経路が分かるようにしました。持っている商品は値段の表示を控えめにして、見やすくしています。</li><li><strong>商品の分類をより正確に</strong> — 自動の取り込みで同じ商品が見つかったとき、より確かな入手経路（購入など）を優先して分類するようにしました。</li><li><strong>起動直後の待ち時間を短縮</strong> — お知らせやアップデートの確認を起動してすぐ行うようにし、商品の読み込みが始まるまでの待ち時間を短くしました。</li></ul><h3 id="不具合修正-25" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-25" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>起動時に、プロダクトキーの確認が二重に行われることがある問題を修正しました。</li></ul><h2 id="v0-4-3-—-2026-06-17" tabindex="-1">v0.4.3 — 2026-06-17 <a class="header-anchor" href="#v0-4-3-—-2026-06-17" aria-label="Permalink to &quot;v0.4.3 — 2026-06-17&quot;">​</a></h2><p>v0.4.2 からの変更です。</p><h3 id="追加された機能-24" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-24" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>アップデートをいつでも手動で確認</strong> — 画面右上の「…」メニューに「アップデートを確認」を追加しました。新しいバージョンがあるかをその場で確認できます。</li><li><strong>アップデートの確認間隔を設定</strong> — 設定の「アップデート」で、起動時にアップデートを確認する間隔を変えられるようになりました。0 にすると、起動するたびに毎回確認します。</li></ul><h3 id="改善-24" tabindex="-1">改善 <a class="header-anchor" href="#改善-24" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>旧バージョンのファイルを薄く表示</strong> — 商品が更新されて入れ替わった古いバージョンのファイルを、現行のファイルと見分けやすいよう薄く表示するようにしました。</li><li><strong>手に入らないファイルはダウンロードできないように</strong> — 「非公開」（BOOTH で配布が終了したファイル）のダウンロードボタンを押せないようにし、理由を表示するようにしました。</li></ul><h2 id="v0-4-2-—-2026-06-16" tabindex="-1">v0.4.2 — 2026-06-16 <a class="header-anchor" href="#v0-4-2-—-2026-06-16" aria-label="Permalink to &quot;v0.4.2 — 2026-06-16&quot;">​</a></h2><p>v0.4.1 からの変更です。</p><h3 id="不具合修正-26" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-26" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>アプリ内のアップデートを行ったあとに、タスクバーの固定（ピン留め）が外れることがある問題を修正しました。</li></ul><h2 id="v0-4-1-—-2026-06-15" tabindex="-1">v0.4.1 — 2026-06-15 <a class="header-anchor" href="#v0-4-1-—-2026-06-15" aria-label="Permalink to &quot;v0.4.1 — 2026-06-15&quot;">​</a></h2><p>v0.4.0 からの変更です。</p><h3 id="追加された機能-25" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-25" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>無料ダウンロードの商品も自動で取り込み</strong> — BOOTH の「無料ダウンロード」履歴にある商品を、購入した商品やギフトと同じように自動でライブラリに取り込むようになりました。取り込んだ商品のカードには「無料DL」の印が付きます。</li></ul><h3 id="改善-25" tabindex="-1">改善 <a class="header-anchor" href="#改善-25" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>手に入らなくなったファイルを「非公開」と表示</strong> — 商品が更新されて古いバージョンのファイルが配布されなくなったときなど、いまは取得できないファイルに「非公開」の印を付けて分かるようにしました。商品まるごとが取り下げられた場合と、一部のファイルだけが入れ替わった場合を見分けられます。</li></ul><h2 id="v0-4-0-—-2026-06-15" tabindex="-1">v0.4.0 — 2026-06-15 <a class="header-anchor" href="#v0-4-0-—-2026-06-15" aria-label="Permalink to &quot;v0.4.0 — 2026-06-15&quot;">​</a></h2><p>v0.3.1 からの変更です。</p><h3 id="追加された機能-26" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-26" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>ヘッダーに「…」メニューを新設</strong> — プロトコルの登録 / 解除と、ダウンロード先フォルダを開く操作を 1 つの「…」メニューにまとめました。このアプリで開く設定になっていないときは、ボタンとメニューに小さな警告アイコンが出ます。</li><li><strong>アプリのアップデートをその場で開始</strong> — 新しいバージョンがあるときに、通知ベル・「…」メニューのいずれからでも、確認のあとアプリ内でダウンロード → 再起動まで行えます。</li><li><strong>ダウンロードキューの状態がアイコンで分かる</strong> — ツールバーのダウンロードボタンが、ダウンロード中・一時停止中・完了の状態を色とアイコンで表すようになりました。</li></ul><h3 id="改善-26" tabindex="-1">改善 <a class="header-anchor" href="#改善-26" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><strong>ファイル更新の通知を商品単位にまとめ</strong> — 1 回の取得で同じ商品に複数のファイルが追加されたときは、通知を 1 件にまとめ、追加されたファイル名をすべて並べて表示します。</li><li><strong>値下げ通知でバリエーションごとの値段を表示</strong> — 複数のバリエーションが同時に値下げされたときは、どのバリエーションがいくらに下がったかをすべて表示します。</li><li>確認ダイアログを開いている間も、画面右下の通知が隠れず手前に表示されるようにしました。</li><li>ショップ一覧モーダルのボタンなど、一部の画面の見た目を整えました。</li></ul><h3 id="不具合修正-27" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-27" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>アプリを更新したあとも、古い「アップデートあり」の通知が残ることがある問題を修正しました。</li><li>スキリストで、矢印キーなどのキーボード操作が効かないことがある問題を修正しました。</li></ul><h2 id="v0-3-1-—-2026-06-15" tabindex="-1">v0.3.1 — 2026-06-15 <a class="header-anchor" href="#v0-3-1-—-2026-06-15" aria-label="Permalink to &quot;v0.3.1 — 2026-06-15&quot;">​</a></h2><p>v0.3.0 からの変更です。</p><h3 id="不具合修正-28" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-28" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>アプリの更新後に、タスクバーの固定 (ピン留め) が外れることがある問題を修正しました。</li></ul><h2 id="v0-3-0-—-2026-06-15" tabindex="-1">v0.3.0 — 2026-06-15 <a class="header-anchor" href="#v0-3-0-—-2026-06-15" aria-label="Permalink to &quot;v0.3.0 — 2026-06-15&quot;">​</a></h2><p>v0.2.0 からの変更です。</p><h3 id="追加された機能-27" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-27" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>通知からのアプリ内アップデート</strong> — 「📦 アップデートあり」通知をクリックすると、確認のあとアプリ内でダウンロード → 再起動まで自動で行います。インストーラ版・ポータブル版・ZIP 版のいずれにも対応します。<a href="/guide/settings#アップデート">設定 &gt; アップデート</a>。</li><li><strong>メタデータ再取得で新規購入も取り込み</strong> — 自動取得が ON のとき、商品情報の再取得に合わせて、新しく購入したアイテムもライブラリに取り込みます。</li><li><strong>単独アイテム作成のカテゴリ + プレビュー</strong> — 手元のファイルを単独アイテムとして登録する際に、BOOTH カテゴリ / カスタムカテゴリを付けられ、カードプレビューでライブラリ上の見え方をその場で確認できます。<a href="/guide/library">ライブラリ画面</a>。</li><li><strong>スキリストにも親カテゴリを付与</strong> — スキリストの BOOTH カテゴリに、公式カテゴリから導出した親カテゴリも付くようになりました (絞り込み・ポップアップで参照できます)。</li><li><strong>空フォルダの自動片付け</strong> — ファイルを削除した結果、商品のダウンロード先フォルダが空になった場合は、そのフォルダも自動で片付けます。</li></ul><h3 id="改善-27" tabindex="-1">改善 <a class="header-anchor" href="#改善-27" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>ユーザーガイド (ドキュメント) を全面的に見直しました — 平易な日本語への統一、説明用スクリーンショットの追加、未記載だった機能 (重複検出・エクスポート/インポート・キャッシュ・ゴミ箱) の追記。</li><li>BOOTH カテゴリの親子解決を高速化しました。</li></ul><h3 id="不具合修正-29" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-29" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>画像 (商品サムネ・ショップアイコン) のキャッシュが消えて毎回読み込み直しになる問題を修正しました。</li><li>小さいウィンドウでモーダルが画面外にはみ出す問題を修正しました。</li><li>スキリスト同期時に、空のカテゴリ / 価格が既存の値を上書きしてしまう問題を修正しました。</li><li>フォロー中ショップの初回新着を取りこぼす問題を修正しました。</li></ul><h2 id="v0-2-0-—-2026-06-11" tabindex="-1">v0.2.0 — 2026-06-11 <a class="header-anchor" href="#v0-2-0-—-2026-06-11" aria-label="Permalink to &quot;v0.2.0 — 2026-06-11&quot;">​</a></h2><p>v0.1.0 からの変更です。</p><h3 id="追加された機能-28" tabindex="-1">追加された機能 <a class="header-anchor" href="#追加された機能-28" aria-label="Permalink to &quot;追加された機能&quot;">​</a></h3><ul><li><strong>複数選択の一括ダウンロード</strong> — 複数アイテムを選択すると画面下部に操作ドックが現れ、選んだアイテムをまとめてダウンロードできます。ドックからはアーカイブ / フォルダへコピー / おすすめリスト書き出し / ゴミ箱への移動もまとめて実行できます。詳しくは <a href="/guide/library#一括選択モード">ライブラリ画面 &gt; 一括選択モード</a>。</li><li><strong>ライブラリ統計ダッシュボード</strong> — 設定タブに、総アイテム数・ダウンロード済み容量・ダウンロード完了率・ショップ別 / カテゴリ別の内訳を表示するダッシュボードを追加しました。<a href="/guide/settings#ライブラリ統計">設定 &gt; ライブラリ統計</a>。</li><li><strong>ショートカットの再割り当て</strong> — キーボード / マウス操作を設定タブから自由に変更できるようになりました (以前は一覧表示のみ)。Esc でキャンセル、↺ でデフォルトに戻せます。<a href="/guide/settings#キーボードショートカット">設定 &gt; キーボードショートカット</a>。</li><li><strong>旧バージョンを一括ダウンロードから除外する設定</strong> — 版違いファイル (v1 / v2 …) があるとき、カードのファイル数表示と一括ダウンロードの対象を現行版のみに絞ります (デフォルト ON)。旧版はデータとして残り、詳細画面から個別にダウンロードできます。</li><li><strong>ライセンスのオフライン悪用対策</strong> — オフラインのまま起動し続けて確認を回避したり、<code>license.json</code> を別 PC にコピーして使い回すことを防ぎます。最後のオンライン確認から 14 日間はオフライン起動できます。<a href="/guide/settings#ライセンス">設定 &gt; ライセンス</a>。</li></ul><h3 id="改善-28" tabindex="-1">改善 <a class="header-anchor" href="#改善-28" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>購入日ソートで、購入順の情報を持たないアイテムも取得した経路の順序で自然に並ぶようになりました。</li><li>ライブラリのメタデータ自動更新を「取得が古いものから」の優先度順に変更しました。</li><li>起動時のアップデート確認をライブラリ取得と並行実行し、起動を高速化しました。</li><li>カードの再描画を差分化・1 フレームにまとめることで、スクロールや一括更新時の表示を高速化しました。</li><li>スキリストの初回表示とスクロール中の描画を高速化しました。</li><li><code>.unitypackage</code> の内容プレビューを高速化しました (解析結果をディスクに保存し、先読みします)。</li><li>起動時のライブラリ同期を分割処理し、起動直後の画面の固まりを軽減しました。</li></ul><h3 id="不具合修正-30" tabindex="-1">不具合修正 <a class="header-anchor" href="#不具合修正-30" aria-label="Permalink to &quot;不具合修正&quot;">​</a></h3><ul><li>トーストを差し替えたときに、古いトーストの自動消滅タイマーが残ってしまう問題を修正しました。</li><li>ダウンロード / 解凍の通知を「1 ファイルにつき 1 トースト」に統一しました。</li></ul><h3 id="内部の変更" tabindex="-1">内部の変更 <a class="header-anchor" href="#内部の変更" aria-label="Permalink to &quot;内部の変更&quot;">​</a></h3><ul><li>多数のリファクタリングを行いました (動作の変更はありません) — モジュール分割、重複処理の共通化、型定義の整理など。</li></ul><div class="tip custom-block"><p class="custom-block-title">フィードバック</p><p>不具合の報告や要望は <a href="https://github.com/ChanyaVRC/booth-package-linker-releases/issues" target="_blank" rel="noreferrer">GitHub Issues</a> へお寄せください。</p></div>',273)])])}const b=l(t,[["render",o]]);export{c as __pageData,b as default};
